  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://example.com/schemas/beta-cruiser.json",
  "title": "beta cruiser",
  "type": "object",
  "additionalProperties": false,
  "required": ["name", "model", "registry", "specs"],
  "properties": {
    "name": {
      "type": "string",
      "minLength": 1,
      "description": "official name of the beta cruiser"
    },
    "model": {
      "type": "string",
      "enum": ["beta-cruiser mk i", "beta-cruiser mk ii", "[tbd]"]
    },
    "registry": {
      "type": "string",
      "pattern": "^bc-[0-9]{4}-[a-z]{2}$",
      "description": "unique hull id in the form bc-0000-xx"
    },
    "role": {
      "type": "string",
      "default": "multi-role cruiser"
    },
    "status": {
      "type": "string",
      "enum": ["prototype", "operational", "decommissioned", "[pending]"]
    },
    "specs": {
      "type": "object",
      "required": ["dimensions", "crew", "propulsion"],
      "properties": {
        "dimensions": {
          "type": "object",
          "required": ["length_m", "beam_m", "height_m"],
          "properties": {
            "length_m": { "type": "number", "minimum": 0 },
            "beam_m": { "type": "number", "minimum": 0 },
            "height_m": { "type": "number", "minimum": 0 }
          },
          "additionalProperties": false
        },
        "mass_tons": { "type": "number", "minimum": 0 },
        "hull_material": { "type": "string", "default": "titanium composite" },
        "crew": {
          "type": "object",
          "required": ["complement", "max"],
          "properties": {
            "complement": { "type": "integer", "minimum": 0 },
            "max": { "type": "integer", "minimum": 0 }
          },
          "additionalProperties": false
        },
        "propulsion": {
          "type": "object",
          "required": ["sublight", "ftl"],
          "properties": {
            "sublight": { "type": "string", "enum": ["ion", "fusion", "magnetoplasma", "[tbd]"] },
            "ftl": { "type": "string", "enum": ["jump-drive", "warp", "none", "[tbd]"] }
          },
          "additionalProperties": false
        },
        "armament": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["type", "count"],
            "properties": {
              "type": { "type": "string", "description": "weapon type, e.g., beam, missile, railgun, [custom]" },
              "count": { "type": "integer", "minimum": 0 },
              "mounts": {
                "type": "array",
                "items": { "type": "string" },
                "description": "mount positions like dorsal, ventral, [slot-a]"
              }
            },
            "additionalProperties": false
          }
        },
        "defense": {
          "type": "object",
          "properties": {
            "shield_rating": { "type": "integer", "minimum": 0 },
            "armor_rating": { "type": "integer", "minimum": 0 },
            "countermeasures": { "type": "array", "items": { "type": "string" } }
          },
          "additionalProperties": false
        },
        "hangar": {
          "type": "object",
          "properties": {
            "capacity": { "type": "integer", "minimum": 0 },
            "craft_types": { "type": "array", "items": { "type": "string" } }
          },
          "additionalProperties": false
        }
      },
      "additionalProperties": false
    },
    "notes": {
      "type": "string",
      "description": "freeform notes; use placeholders like [redacted] or [to be decided]"
    }
  }
}

