      ResultSet rs = stmt.executeQuery(sql);

      if (rs.next()) {
        // Também arriscado: refletir entrada do usuário sem escape pode causar XSS
        response.getWriter().println("Bem-vindo, " + user);
      } else {
        response.getWriter().println("Credenciais inválidas");
      }
    } catch (SQLException e) {
      response.sendError(500);
    }
  }
}

