import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.sql.*;
import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.*;

// Correção: usar PreparedStatement com parâmetros e evitar refletir entrada sem escape
@WebServlet("/login-seguro")
public class LoginServletSeguro extends HttpServlet {
  @Override
  protected void doPost(HttpServletRequest request, HttpServletResponse response)
      throws ServletException, IOException {

    String user = request.getParameter("user");
    String pass = request.getParameter("pass");

    String sql = "SELECT id FROM users WHERE username = ? AND password_hash = ?";

    try (Connection conn = DriverManager.getConnection("jdbc:postgresql://localhost/app", "app", "secret");
         PreparedStatement ps = conn.prepareStatement(sql)) {

      ps.setString(1, user);          // Parâmetro bindado: evita injeção
      ps.setBytes(2, sha256(pass));   // Exemplo: comparar hash da senha

      try (ResultSet rs = ps.executeQuery()) {
        if (rs.next()) {
          // Não refletir o valor informado pelo usuário sem saneamento/escape
          response.getWriter().println("Login realizado com sucesso.");
        } else {
          response.getWriter().println("Credenciais inválidas");
        }
      }
    } catch (SQLException e) {
      response.sendError(500);
    }
  }

  private static byte[] sha256(String s) {
    try {
      MessageDigest md = MessageDigest.getInstance("SHA-256");
      return md.digest(s.getBytes(StandardCharsets.UTF_8));
    } catch (Exception e) {
      throw new RuntimeException(e);
    }
  }
}

